export interface ConnectorConfig {
  /** Pipedrive API token (from env var PIPEDRIVE_API_TOKEN) */
  pipedriveApiToken: string;
  /** Pipedrive company domain, e.g. "mycompany" for mycompany.pipedrive.com */
  pipedriveCompanyDomain: string;
  /** Mapping of semantic field names to Typeform field IDs */
  typeformFieldIds: {
    /** Field ID for the person's name */
    nameFieldId: string;
    /** Field ID for the email address */
    emailFieldId: string;
    /** Field ID for the phone number */
    phoneFieldId: string;
    /** Field ID for the company/organization name */
    companyFieldId: string;
    /** Field ID for the deal title (first text answer) */
    dealTitleFieldId: string;
  };
  /** Injected fetch for testing; defaults to global fetch */
  fetch?: typeof fetch;
}

export interface TypeformWebhookPayload {
  event_id: string;
  event_type: string;
  form_response: {
    form_id: string;
    token: string;
    submitted_at: string;
    answers: Array<{
      type: string;
      text?: string;
      email?: string;
      field: {
        id: string;
        type: string;
      };
    }>;
  };
}

export interface HandleResult {
  organizationId: number;
  personId: number;
  dealId: number;
}

function getAnswerValue(
  answers: TypeformWebhookPayload['form_response']['answers'],
  fieldId: string,
): string | undefined {
  const answer = answers.find((a) => a.field.id === fieldId);
  if (!answer) return undefined;
  return answer.text ?? answer.email;
}

function requireValue(
  value: string | undefined,
  fieldName: string,
): string {
  if (value === undefined || value === '') {
    throw new Error(`Missing required field: ${fieldName}`);
  }
  return value;
}

async function pipedrivePost<T>(
  config: ConnectorConfig,
  path: string,
  body: unknown,
): Promise<T> {
  const url = `https://${config.pipedriveCompanyDomain}.pipedrive.com/api/v2${path}?api_token=${encodeURIComponent(config.pipedriveApiToken)}`;
  const fetchFn = config.fetch ?? fetch;
  const response = await fetchFn(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
  if (!response.ok) {
    throw new Error(`Pipedrive API error: ${response.status} ${response.statusText} for ${path}`);
  }
  return response.json() as Promise<T>;
}

interface OrganizationResponse {
  data: { id: number; name: string };
}
interface PersonResponse {
  data: { id: number; name: string; org_id: number };
}
interface DealResponse {
  data: { id: number; title: string; person_id: number; org_id: number };
}

export async function handle(
  payload: TypeformWebhookPayload,
  config: ConnectorConfig,
): Promise<HandleResult> {
  if (!payload.form_response?.answers?.length) {
    throw new Error('Invalid payload: missing form_response.answers');
  }

  const answers = payload.form_response.answers;
  const fieldIds = config.typeformFieldIds;

  const companyName = requireValue(getAnswerValue(answers, fieldIds.companyFieldId), 'company');
  const personName = requireValue(getAnswerValue(answers, fieldIds.nameFieldId), 'name');
  const email = requireValue(getAnswerValue(answers, fieldIds.emailFieldId), 'email');
  const phone = requireValue(getAnswerValue(answers, fieldIds.phoneFieldId), 'phone');
  const dealTitle = requireValue(getAnswerValue(answers, fieldIds.dealTitleFieldId), 'dealTitle');

  // 1. Create organization
  const orgResponse = await pipedrivePost<OrganizationResponse>(config, '/organizations', {
    name: companyName,
  });
  const organizationId = orgResponse.data.id;

  // 2. Create person linked to organization
  const personResponse = await pipedrivePost<PersonResponse>(config, '/persons', {
    name: personName,
    email: [{ value: email, primary: true, label: 'work' }],
    phone: [{ value: phone, primary: true, label: 'work' }],
    org_id: organizationId,
  });
  const personId = personResponse.data.id;

  // 3. Create deal linked to person
  const dealResponse = await pipedrivePost<DealResponse>(config, '/deals', {
    title: dealTitle,
    person_id: personId,
  });
  const dealId = dealResponse.data.id;

  return { organizationId, personId, dealId };
}

