import { handle, ConnectorConfig, TypeformWebhookPayload } from './connector';
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall,
} from './fixtures';

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch();
    const config: ConnectorConfig = {
      pipedriveApiToken: 'test-token',
      pipedriveCompanyDomain: 'testco',
      typeformFieldIds: {
        nameFieldId: 'name_field_id',
        emailFieldId: 'email_field_id',
        phoneFieldId: 'phone_field_id',
        companyFieldId: 'company_field_id',
        dealTitleFieldId: 'text_answer_field_id',
      },
      fetch,
    };
    const result = await handle(SOURCE_EXAMPLE as unknown as TypeformWebhookPayload, config);
    expect(calls.length).toBeGreaterThan(0);
    expect(result).toEqual({ organizationId: 123, personId: 456, dealId: 789 });
  });
});

describe('handle', () => {
  let baseConfig: ConnectorConfig;
  let validPayload: TypeformWebhookPayload;

  beforeEach(() => {
    baseConfig = {
      pipedriveApiToken: 'test-token',
      pipedriveCompanyDomain: 'testco',
      typeformFieldIds: {
        nameFieldId: 'name_field_id',
        emailFieldId: 'email_field_id',
        phoneFieldId: 'phone_field_id',
        companyFieldId: 'company_field_id',
        dealTitleFieldId: 'text_answer_field_id',
      },
    };
    validPayload = {
      event_id: 'evt1',
      event_type: 'form_response',
      form_response: {
        form_id: 'f1',
        token: 'tok',
        submitted_at: '2024-01-01T00:00:00Z',
        answers: [
          { type: 'text', text: 'Acme Corp', field: { id: 'company_field_id', type: 'short_text' } },
          { type: 'text', text: 'John Doe', field: { id: 'name_field_id', type: 'short_text' } },
          { type: 'email', email: 'john@example.com', field: { id: 'email_field_id', type: 'email' } },
          { type: 'text', text: '+15551234', field: { id: 'phone_field_id', type: 'short_text' } },
          { type: 'text', text: 'Big Deal', field: { id: 'text_answer_field_id', type: 'short_text' } },
        ],
      },
    };
  });

  it('happy path creates org, person, deal and returns ids', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.url.includes('/organizations')) return jsonResponse({ data: { id: 10, name: 'Acme Corp' } }, 201);
      if (req.url.includes('/persons')) return jsonResponse({ data: { id: 20, name: 'John Doe', org_id: 10 } }, 201);
      if (req.url.includes('/deals')) return jsonResponse({ data: { id: 30, title: 'Big Deal', person_id: 20, org_id: 10 } }, 201);
      return jsonResponse({ error: 'not found' }, 404);
    });

    const result = await handle(validPayload, { ...baseConfig, fetch });
    expect(result).toEqual({ organizationId: 10, personId: 20, dealId: 30 });
    expect(calls).toHaveLength(3);

    // Verify request bodies
    expect(calls[0].json).toEqual({ name: 'Acme Corp' });
    expect(calls[1].json).toEqual({
      name: 'John Doe',
      email: [{ value: 'john@example.com', primary: true, label: 'work' }],
      phone: [{ value: '+15551234', primary: true, label: 'work' }],
      org_id: 10,
    });
    expect(calls[2].json).toEqual({ title: 'Big Deal', person_id: 20 });
  });

  it('includes api_token as query parameter', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.url.includes('/organizations')) return jsonResponse({ data: { id: 1, name: 'x' } }, 201);
      if (req.url.includes('/persons')) return jsonResponse({ data: { id: 2, name: 'x', org_id: 1 } }, 201);
      if (req.url.includes('/deals')) return jsonResponse({ data: { id: 3, title: 'x', person_id: 2, org_id: 1 } }, 201);
      return jsonResponse({ error: 'not found' }, 404);
    });

    await handle(validPayload, { ...baseConfig, fetch });
    for (const call of calls) {
      expect(call.url).toContain('api_token=test-token');
    }
  });

  it('throws descriptive error when company field is missing', async () => {
    const payloadMissingCompany = {
      ...validPayload,
      form_response: {
        ...validPayload.form_response,
        answers: validPayload.form_response.answers.filter((a) => a.field.id !== 'company_field_id'),
      },
    };
    const { fetch } = fakeFetch(() => jsonResponse({}, 201));
    await expect(handle(payloadMissingCompany, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: company');
  });

  it('throws descriptive error when name field is missing', async () => {
    const payloadMissingName = {
      ...validPayload,
      form_response: {
        ...validPayload.form_response,
        answers: validPayload.form_response.answers.filter((a) => a.field.id !== 'name_field_id'),
      },
    };
    const { fetch } = fakeFetch(() => jsonResponse({}, 201));
    await expect(handle(payloadMissingName, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: name');
  });

  it('throws descriptive error when email field is missing', async () => {
    const payloadMissingEmail = {
      ...validPayload,
      form_response: {
        ...validPayload.form_response,
        answers: validPayload.form_response.answers.filter((a) => a.field.id !== 'email_field_id'),
      },
    };
    const { fetch } = fakeFetch(() => jsonResponse({}, 201));
    await expect(handle(payloadMissingEmail, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: email');
  });

  it('throws descriptive error when phone field is missing', async () => {
    const payloadMissingPhone = {
      ...validPayload,
      form_response: {
        ...validPayload.form_response,
        answers: validPayload.form_response.answers.filter((a) => a.field.id !== 'phone_field_id'),
      },
    };
    const { fetch } = fakeFetch(() => jsonResponse({}, 201));
    await expect(handle(payloadMissingPhone, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: phone');
  });

  it('throws descriptive error when deal title field is missing', async () => {
    const payloadMissingDealTitle = {
      ...validPayload,
      form_response: {
        ...validPayload.form_response,
        answers: validPayload.form_response.answers.filter((a) => a.field.id !== 'text_answer_field_id'),
      },
    };
    const { fetch } = fakeFetch(() => jsonResponse({}, 201));
    await expect(handle(payloadMissingDealTitle, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: dealTitle');
  });

  it('throws on non-2xx response from organizations endpoint', async () => {
    const { fetch } = fakeFetch((req: RecordedCall) => {
      if (req.url.includes('/organizations')) return jsonResponse({ error: 'unauthorized' }, 401);
      return jsonResponse({}, 201);
    });
    await expect(handle(validPayload, { ...baseConfig, fetch })).rejects.toThrow('Pipedrive API error: 401 Unauthorized for /organizations');
  });

  it('throws on non-2xx response from persons endpoint', async () => {
    const { fetch } = fakeFetch((req: RecordedCall) => {
      if (req.url.includes('/organizations')) return jsonResponse({ data: { id: 1, name: 'x' } }, 201);
      if (req.url.includes('/persons')) return jsonResponse({ error: 'forbidden' }, 403);
      return jsonResponse({}, 201);
    });
    await expect(handle(validPayload, { ...baseConfig, fetch })).rejects.toThrow('Pipedrive API error: 403 Forbidden for /persons');
  });

  it('throws on non-2xx response from deals endpoint', async () => {
    const { fetch } = fakeFetch((req: RecordedCall) => {
      if (req.url.includes('/organizations')) return jsonResponse({ data: { id: 1, name: 'x' } }, 201);
      if (req.url.includes('/persons')) return jsonResponse({ data: { id: 2, name: 'x', org_id: 1 } }, 201);
      if (req.url.includes('/deals')) return jsonResponse({ error: 'conflict' }, 409);
      return jsonResponse({}, 201);
    });
    await expect(handle(validPayload, { ...baseConfig, fetch })).rejects.toThrow('Pipedrive API error: 409 Conflict for /deals');
  });

  it('throws when payload has no answers array', async () => {
    const badPayload = {
      ...validPayload,
      form_response: { ...validPayload.form_response, answers: [] },
    };
    const { fetch } = fakeFetch(() => jsonResponse({}, 201));
    await expect(handle(badPayload, { ...baseConfig, fetch })).rejects.toThrow('Invalid payload: missing form_response.answers');
  });
});

